def evaluate(row,w):
    t=(complex(w)-CENTER)/RADIUS
    if abs(t)>1:raise ValueError("q030 q025-centered Taylor extrapolation forbidden")
    return {k:complex(np.polynomial.polynomial.polyval(t,[
        complex(*v) for v in row[k+"_coeff_scaled"]]))
        for k in ("chiJ","chiX")}
